draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // draw a symbolic object, LxxxIV (Roman numeral for 84)
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);
  ctx.fillText('L', W/2-30, H/2-20+Math.sin(t)*10);
  ctx.fillText('XXX', W/2-10, H/2+20+Math.sin(t)*10);
  ctx.fillText('IV', W/2+30, H/2-20+Math.sin(t)*10);
  ctx.restore();
}
